head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[calendar > M > gotoToday]<br/>Calendar 컴포넌트의 선택일을 오늘 날짜로 설정하며 달력을 이동합니다.",
    "validation" : [
        "gotoToday() 메소드 호출 시 Calendar 컴포넌트의 선택일을 오늘 날짜로 설정하며 달력을 이동합니다.",
        "날짜 이동 후 getValue() 메소드의 반환값이 이동 전과 다르면 onchange 이벤트가 발생합니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {}

    let cList = $c.gcm.createCList(properties);
    let eList = $c.gcm.createEList(["onchange"]);

    await $c.gcm.createBasicCalendar(cList, eList);
    // createBasicCalendar 내부에서 gotoCalendar('20251111') 호출 → 초기 선택일: 2025-11-11
}



// gotoToday() 호출 → 선택일을 오늘 날짜로 설정하며 달력 이동
// validation: gotoToday 호출 시 getValue() 가 WebSquare.date.getCurrentServerDate() 와 일치하는지 확인
scwin.btn_gotoToday_onclick = function (e) {
    target1.gotoToday();
    let afterValue = target1.getValue();
    let todayValue = WebSquare.date.getCurrentServerDate();
    wf_body_bottom.getObj("scwin").setReturnValue("[오늘 날짜 일치 성공 여부] " + (afterValue === todayValue));
};



// 날짜 이동 후 getValue() 반환값이 이동 전과 다르면 onchange 이벤트 발생
// @spec validation
scwin.target1_onchange = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("[onchange 발생] getValue() 반환값이 이동 전과 달라 onchange 핸들러 호출됨");
};
